def pick(L, t, ch, j=0):
    i = (t + 4 * (ch - 1 + j)) % len(L); return i, L[i]
def other(L, i, k, n=3): return [L[(i + 1 + s * 3) % len(L)][k] for s in range(n)]

def gram_mcq(t, ch):
    """12 grammar/vocabulary MCQs for tier index t (0..3) in chapter ch."""
    out = []
    i, r = pick(SYN, t, ch); out.append(M4(f"'{r[0]}' का पर्यायवाची शब्द है —", r[1], other(SYN, i, 1), f"{r[0]} = {r[1]}"))
    i, r = pick(ANT, t, ch); out.append(M4(f"'{r[0]}' का विलोम शब्द है —", r[1], other(ANT, i, 1), f"{r[0]} का विलोम {r[1]}"))
    i, r = pick(SANDHI, t, ch); out.append(M4(f"'{r[0]}' का सही संधि-विच्छेद है —", r[1], other(SANDHI, i, 1), f"{r[1]} = {r[0]} ({r[2]})"))
    i, r = pick(SAMAS, t, ch); out.append(M4(f"'{r[0]}' में कौन-सा समास है?", r[2], [x for x in SAMAS_NAMES if x != r[2]][:3], f"विग्रह: {r[1]} — {r[2]}"))
    i, r = pick(MUH, t, ch); out.append(M4(f"मुहावरे '{r[0]}' का अर्थ है —", r[1], other(MUH, i, 1), f"{r[0]} = {r[1]}"))
    i, r = pick(MUH, t, ch, 1); out.append(M4(f"'{r[1]}' — इस अर्थ के लिए उपयुक्त मुहावरा है —", r[0], other(MUH, i, 0), f"अर्थ '{r[1]}' के लिए {r[0]}"))
    i, r = pick(VAK_R, t, ch); out.append(M4(f"रचना के आधार पर वाक्य '{r[0]}' किस प्रकार का है?", r[1], [x for x in ["सरल वाक्य", "संयुक्त वाक्य", "मिश्र वाक्य"] if x != r[1]] + ["विस्मयादिबोधक वाक्य"], r[1]))
    i, r = pick(VAK_A, t, ch); out.append(M4(f"अर्थ के आधार पर वाक्य '{r[0]}' किस प्रकार का है?", r[1], [x for x in ["विधानवाचक वाक्य", "निषेधवाचक वाक्य", "प्रश्नवाचक वाक्य", "आज्ञावाचक वाक्य", "इच्छावाचक वाक्य"] if x != r[1]][:3], r[1]))
    r = RAS[t + 4 * (ch % 2)]; out.append(M4(f"काव्य-पंक्ति '{r[0]}' में कौन-सा रस है?", r[1], [x[1] for x in RAS if x[1] != r[1]][:3], f"स्थायी भाव {r[2]}: {r[1]}"))
    r = ALA[t + 4 * (ch % 2)]; out.append(M4(f"'{r[0]}' में कौन-सा अलंकार है?", r[1], [x[1] for x in ALA if x[1] != r[1]][:3], f"{r[1]}: {r[2]}"))
    if ch % 2:
        i, r = pick(UPS, t, ch); out.append(M4(f"'{r[0]}' शब्द में उपसर्ग है —", r[1], [x[1] for x in UPS if x[1] != r[1]][:3], f"{r[0]} = {r[1]} + मूल शब्द"))
    else:
        i, r = pick(PRA, t, ch); out.append(M4(f"'{r[0]}' शब्द में प्रत्यय है —", r[1], [x[1] for x in PRA if x[1] != r[1]][:3], f"{r[0]} में प्रत्यय '{r[1]}'"))
    i, r = pick(EKSH, t, ch); out.append(M4(f"'{r[0]}' — के लिए एक शब्द है —", r[1], other(EKSH, i, 1), f"{r[0]} = {r[1]}"))
    return out

def _pk(L, t, ch, j, n):
    i = (t + 4 * (ch - 1 + j)) % len(L); return [L[(i + 4 * s) % len(L)] for s in range(n)]

def gram_B(t, ch):
    """4 grammar 2-mark questions."""
    s = _pk(SANDHI, t, ch, 2, 2); m = _pk(SAMAS, t, ch, 2, 2); h = _pk(MUH, t, ch, 3, 2); e = _pk(EKSH, t, ch, 1, 4)
    a = _pk(ANT, t, ch, 2, 2); y = _pk(SYN, t, ch, 2, 2)
    out = [Q(f"संधि-विच्छेद कीजिए और संधि का भेद लिखिए — (i) {s[0][0]} (ii) {s[1][0]}", f"(i) {s[0][0]} = {s[0][1]} ({s[0][2]}) (1) (ii) {s[1][0]} = {s[1][1]} ({s[1][2]}) (1)", "1+1"),
           Q(f"समास-विग्रह कीजिए और समास का नाम लिखिए — (i) {m[0][0]} (ii) {m[1][0]}", f"(i) {m[0][1]} — {m[0][2]} (1) (ii) {m[1][1]} — {m[1][2]} (1)", "1+1"),
           Q(f"निम्नलिखित मुहावरों का अर्थ लिखिए — (i) {h[0][0]} (ii) {h[1][0]}", f"(i) {h[0][0]}: {h[0][1]} (1) (ii) {h[1][0]}: {h[1][1]} (1)", "1+1")]
    if (ch + t) % 2:
        out.append(Q(f"निम्नलिखित के लिए एक शब्द लिखिए — (i) {e[0][0]} (ii) {e[1][0]} (iii) {e[2][0]} (iv) {e[3][0]}", f"(i) {e[0][1]} (ii) {e[1][1]} (iii) {e[2][1]} (iv) {e[3][1]} (½ × 4)", "½+½+½+½"))
    else:
        out.append(Q(f"(i) '{y[0][0]}' और '{y[1][0]}' के एक-एक पर्यायवाची तथा (ii) '{a[0][0]}' और '{a[1][0]}' के एक-एक विलोम शब्द लिखिए।", f"(i) {y[0][0]} — {y[0][1]}; {y[1][0]} — {y[1][1]} (1) (ii) {a[0][0]} — {a[0][1]}; {a[1][0]} — {a[1][1]} (1)", "1+1"))
    return out

def gram_C(t, ch):
    """6 grammar 3-mark questions."""
    r = RAS[t + 4 * ((ch + 1) % 2)]; a = ALA[t + 4 * ((ch + 1) % 2)]
    v = _pk(VAK_R, t, ch, 1, 3); w = _pk(VAK_A, t, ch, 1, 2); mu = _pk(MUH, t, ch, 5, 3); sa = _pk(SANDHI, t, ch, 6, 3); sm = _pk(SAMAS, t, ch, 6, 3)
    return [Q(f"काव्य-पंक्ति पढ़कर रस पहचानिए तथा उसका स्थायी भाव लिखिए — '{r[0]}'", f"रस: {r[1]} (1½); स्थायी भाव: {r[2]} (½); कारण: पंक्ति के दृश्य/भाव इसी रस के आलंबन-उद्दीपन हैं (1)", "2+1"),
            Q(f"अलंकार पहचानकर कारण सहित लिखिए — '{a[0]}'", f"अलंकार: {a[1]} (1); कारण: {a[2]} (2)", "1+2"),
            Q(f"रचना के आधार पर वाक्य-भेद लिखिए — (i) {v[0][0]} (ii) {v[1][0]} (iii) {v[2][0]}", f"(i) {v[0][1]} (ii) {v[1][1]} (iii) {v[2][1]} (1 × 3)", "1+1+1"),
            Q(f"अर्थ के आधार पर वाक्य-भेद लिखिए — (i) {w[0][0]} (ii) {w[1][0]}; और एक निषेधवाचक वाक्य स्वयं बनाइए।", f"(i) {w[0][1]} (1) (ii) {w[1][1]} (1) 'नहीं/न' से युक्त उचित निषेधवाचक वाक्य (1)", "1+1+1"),
            Q(f"निम्नलिखित मुहावरों का अर्थ लिखिए और वाक्यों में प्रयोग कीजिए — (i) {mu[0][0]} (ii) {mu[1][0]} (iii) {mu[2][0]}", f"अर्थ: (i) {mu[0][1]} (ii) {mu[1][1]} (iii) {mu[2][1]} (½ × 3); उचित वाक्य-प्रयोग (½ × 3)", "1½+1½"),
            Q(f"संधि-विच्छेद तथा समास-विग्रह कीजिए — (i) {sa[0][0]} (ii) {sa[1][0]} (iii) {sm[0][0]} (iv) {sm[1][0]} (v) {sm[2][0]} (vi) {sa[2][0]}", f"(i) {sa[0][1]} (ii) {sa[1][1]} (iii) {sm[0][1]} ({sm[0][2]}) (iv) {sm[1][1]} ({sm[1][2]}) (v) {sm[2][1]} ({sm[2][2]}) (vi) {sa[2][1]} (½ × 6)", "½×6")]
